// Valores fictícios. Realizado e comprometido são valores distintos, nunca somados duas vezes.
const budgetSeed={budgets:[{year:2026,area:'Atendimento',amount:30000},{year:2026,area:'Tecnologia',amount:45000},{year:2026,area:'Liderança',amount:25000},{year:2026,area:'RH',amount:15000}],entries:[{name:'Atendimento com propósito',area:'Atendimento',date:'2026-03-10',paid:12000,reserved:3000,participants:30},{name:'Segurança da informação',area:'Tecnologia',date:'2026-06-15',paid:18000,reserved:8000,participants:60},{name:'Feedback que desenvolve',area:'Liderança',date:'2026-08-12',paid:9000,reserved:6000,participants:20},{name:'Diagnóstico de competências',area:'RH',date:'2026-09-20',paid:4000,reserved:2000,participants:10}]};
let finance;try{finance=JSON.parse(localStorage.getItem('forma-budget-v1'))||structuredClone(budgetSeed)}catch{finance=structuredClone(budgetSeed)}let financeYear=2026,financeArea='Todas';const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);const persistFinance=()=>localStorage.setItem('forma-budget-v1',JSON.stringify(finance));
const navBudget=document.createElement('button');navBudget.dataset.view='budget';navBudget.textContent='◉ Orçamento de T&D';document.querySelector('nav').append(navBudget);names.budget='Orçamento de T&D';
function financeData(){return finance.budgets.filter(b=>b.year===financeYear&&(financeArea==='Todas'||b.area===financeArea)).map(b=>{const entries=finance.entries.filter(e=>+e.date.slice(0,4)===b.year&&e.area===b.area);const paid=entries.reduce((s,e)=>s+e.paid,0),reserved=entries.reduce((s,e)=>s+e.reserved,0);return {...b,paid,reserved,balance:b.amount-paid-reserved}})}
function budgetView(){const rows=financeData(),total=rows.reduce((s,r)=>({amount:s.amount+r.amount,paid:s.paid+r.paid,reserved:s.reserved+r.reserved,balance:s.balance+r.balance}),{amount:0,paid:0,reserved:0,balance:0});const entries=finance.entries.map((e,i)=>({...e,id:i})).filter(e=>+e.date.slice(0,4)===financeYear&&(financeArea==='Todas'||e.area===financeArea));const areas=[...new Set(finance.budgets.map(b=>b.area))].sort();const years=[...new Set([financeYear,...finance.budgets.map(b=>b.year)])].sort();const max=Math.max(1,...rows.flatMap(r=>[r.amount,r.paid+r.reserved]));
content.innerHTML=heading('Cada investimento, à vista.','Orçamento anual de treinamentos por área. Dados fictícios, editáveis neste navegador.')+`<div class="finance-filters"><label>Ano<select id="financeYear">${years.map(y=>`<option ${y===financeYear?'selected':''}>${y}</option>`).join('')}</select></label><label>Área<select id="financeArea"><option>Todas</option>${areas.map(a=>`<option ${a===financeArea?'selected':''}>${esc(a)}</option>`).join('')}</select></label><button data-finance="export">↓ Exportar dados CSV</button><button data-finance="print">Imprimir painel</button></div><div class="stats"><div class="stat"><label>Orçamento aprovado</label><strong>${money(total.amount)}</strong><small>Verba anual das áreas selecionadas</small></div><div class="stat"><label>Já utilizado · realizado</label><strong>${money(total.paid)}</strong><small>Valores registrados como pagos</small></div><div class="stat"><label>Comprometido · a pagar</label><strong>${money(total.reserved)}</strong><small>Reserva aprovada ainda não paga</small></div><div class="stat"><label>Disponível para novas ações</label><strong class="${total.balance<0?'danger':''}">${money(total.balance)}</strong><small>Orçamento − realizado − comprometido</small></div></div><div class="grid"><div class="panel"><h2>Uso do orçamento por área</h2><p>Escala comum em reais. Compare a verba com os valores já pagos e reservados.</p><div class="legend"><span>● Orçamento</span><span>● Realizado</span><span>● Comprometido</span></div>${rows.map(r=>`<div class="budget-bar"><b>${esc(r.area)}</b><div class="bar-line"><i style="width:${r.amount/max*100}%"></i><span>${money(r.amount)}</span></div><div class="bar-line spent"><i style="width:${r.paid/max*100}%"></i><i class="reserved" style="width:${r.reserved/max*100}%"></i><span>${money(r.paid+r.reserved)}</span></div></div>`).join('')||'<p>Nenhum orçamento neste filtro.</p>'}</div><div class="panel"><h2>Quanto ainda pode ser investido?</h2><p>Saldo por área após considerar pagamentos e reservas.</p>${rows.map(r=>`<div class="project"><div class="project-info"><strong>${esc(r.area)}</strong><p>${r.amount?((r.paid+r.reserved)/r.amount*100).toFixed(1)+'% da verba utilizada ou reservada':'Sem verba aprovada'}</p></div><strong class="${r.balance<0?'danger':''}">${money(r.balance)}</strong></div>`).join('')}<div class="note">${rows.some(r=>r.balance<0)?'Atenção: há uma área com saldo negativo. Revise o orçamento ou os compromissos.':'O saldo disponível considera compromissos ainda não pagos.'}</div></div></div><div class="panel full"><h2>Detalhamento por área</h2><div class="table-scroll"><table><thead><tr><th>Área</th><th>Aprovado</th><th>Realizado</th><th>Comprometido</th><th>Disponível</th><th>Utilização + reserva</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.area)}</td><td>${money(r.amount)}</td><td>${money(r.paid)}</td><td>${money(r.reserved)}</td><td class="${r.balance<0?'danger':''}">${money(r.balance)}</td><td>${r.amount?((r.paid+r.reserved)/r.amount*100).toFixed(1)+'%':'Não calculável'}</td></tr>`).join('')}</tbody></table></div></div><div class="panel full"><h2>Treinamentos e valores registrados</h2><p>A data representa a competência do registro financeiro. Uma compra compartilhada deve ser dividida entre as áreas, sem duplicar o valor total.</p><div class="table-scroll"><table><thead><tr><th>Treinamento</th><th>Área / data</th><th>Pago</th><th>A pagar</th><th>Participações previstas</th><th>Ação</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.area)}<br>${e.date.split('-').reverse().join('/')}</td><td>${money(e.paid)}</td><td>${money(e.reserved)}</td><td>${e.participants}</td><td><button class="text-button" data-edit-entry="${e.id}">Editar</button></td></tr>`).join('')}</tbody></table></div><p class="note">Ao pagar uma reserva, aumente o valor pago e reduza o valor a pagar. Assim o compromisso não será contado duas vezes.</p></div><div class="grid full"><form id="budgetForm" class="panel"><h2>Definir orçamento por área</h2><label>Área<input name="area" required maxlength="60" value="${financeArea==='Todas'?'':esc(financeArea)}"></label><label>Ano<input name="year" type="number" min="2020" max="2100" required value="${financeYear}"></label><label>Verba aprovada (R$)<input name="amount" type="number" min="0" step="0.01" required></label><p>Salvar substitui a verba existente para a mesma área e ano. Os lançamentos são preservados.</p><button class="primary">Salvar orçamento</button></form><form id="entryForm" class="panel"><h2 id="entryTitle">Registrar treinamento</h2><input type="hidden" name="id" value=""><label>Treinamento<input name="name" required maxlength="100"></label><label>Área<select name="area" required>${areas.map(a=>`<option>${esc(a)}</option>`).join('')}</select></label><label>Data de competência<input name="date" type="date" required min="2020-01-01" max="2100-12-31" value="${financeYear}-10-14"></label><div class="form-pair"><label>Valor pago (R$)<input name="paid" type="number" min="0" step="0.01" value="0" required></label><label>Saldo a pagar (R$)<input name="reserved" type="number" min="0" step="0.01" value="0" required></label></div><label>Participações previstas<input name="participants" type="number" min="0" step="1" value="0" required></label><button class="primary">Salvar treinamento</button><p id="financeMessage" role="status"></p></form></div>`;
}
const originalRender=render;render=function(){originalRender();if(view==='budget')budgetView();if(view==='overview'){content.querySelector('.ring').innerHTML='50%<small>PROJETO GERAL</small>';const c=document.createElement('div');c.className='panel full';c.innerHTML='<div class="panel-head"><div><h2>Transparência do investimento</h2><p>Veja o que cada área já utilizou, comprometeu e ainda tem disponível.</p></div><button class="primary" data-go="budget">Ver orçamento →</button></div>';content.prepend(c)}if(view==='kpis'){const c=document.createElement('div');c.className='panel full';c.innerHTML='<h2>Investimento e resultados são acompanhados juntos</h2><p>Os gráficos de orçamento mostram execução financeira por área. Conclusão, satisfação e aplicação precisam de registros reais de avaliações e do LMS.</p><button class="primary" data-go="budget">Abrir gráficos de orçamento →</button><p>Referências: <a href="https://www.cipd.org/uk/knowledge/factsheets/evaluating-learning-factsheet/" target="_blank" rel="noopener">CIPD · avaliação e transferência da aprendizagem</a> · <a href="https://www.td.org/content/atd-blog/2026-state-of-the-industry-report-indicates-latest-td-trends" target="_blank" rel="noopener">ATD · indicadores de T&D em 2026</a></p>';content.append(c)}};
document.addEventListener('change',e=>{if(e.target.id==='financeYear'){financeYear=+e.target.value;render()}if(e.target.id==='financeArea'){financeArea=e.target.value;render()}});
document.addEventListener('submit',e=>{if(e.target.id==='budgetForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),year=+d.year,amount=+d.amount;const existing=finance.budgets.find(b=>b.year===year&&b.area.toLocaleLowerCase('pt-BR')===d.area.trim().toLocaleLowerCase('pt-BR'));if(existing)existing.amount=amount;else finance.budgets.push({year,area:d.area.trim(),amount});financeYear=year;financeArea=existing?.area||d.area.trim();persistFinance();render()}if(e.target.id==='entryForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!finance.budgets.some(b=>b.area===d.area&&b.year===+d.date.slice(0,4))){document.querySelector('#financeMessage').textContent='Defina primeiro o orçamento desta área para o ano escolhido.';return}const item={name:d.name.trim(),area:d.area,date:d.date,paid:+d.paid,reserved:+d.reserved,participants:+d.participants};if(d.id==='')finance.entries.push(item);else finance.entries[+d.id]=item;persistFinance();render()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.editEntry!==undefined){const f=document.querySelector('#entryForm'),item=finance.entries[+b.dataset.editEntry];Object.entries({...item,id:b.dataset.editEntry}).forEach(([k,v])=>f.elements[k].value=v);document.querySelector('#entryTitle').textContent='Editar treinamento';f.scrollIntoView({behavior:'smooth'})}if(b.dataset.finance==='print')window.print();if(b.dataset.finance==='export'){const cell=v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';const header=['Ano','Area','Aprovado','Realizado','Comprometido','Disponivel'];const lines=[header,...financeData().map(r=>[r.year,r.area,r.amount,r.paid,r.reserved,r.balance])];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='orcamento-td-'+financeYear+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});render();
